/*
 * Tsuru — módulo autocontenido del asistente de VólticvS.
 *
 * Uso: JC solo agrega esta línea al final de su <body>, nada más:
 *     <script src="tsuru.js"></script>
 *
 * Qué hace solo, sin que JC configure nada:
 *  - Inyecta su propio CSS (todo prefijado "tsuru-", no choca con los estilos de JC)
 *  - Crea sus propios elementos (sprite, burbuja de texto, barra de progreso)
 *  - Lee el HTML de JC buscando las etiquetas de texto conocidas para saber
 *    hacia dónde caminar (ver ETIQUETAS más abajo)
 *  - Corre la encuesta completa: accesibilidad, ubicación, 8 preguntas base,
 *    puerta a la versión extendida, 10 preguntas avanzadas, resumen final
 *
 * Limitación real, no maquillada: la búsqueda de "hacia dónde caminar" es por
 * texto conocido, no comprensión real de cualquier página. Si JC cambia el
 * texto de una etiqueta, hay que actualizar ETIQUETAS acá abajo. Una versión
 * que entienda cualquier HTML sin curaduría previa requeriría mandarle el DOM
 * a un LLM en tiempo real (ej. Groq) — eso es una fase aparte, no esto.
 */
(function(){
  'use strict';

  const SPRITE_B64 = "";

  // ---------- CSS propio, inyectado, todo prefijado tsuru- ----------
  const css = `
    #tsuru-sprite{position:fixed;width:50px;height:100px;left:40px;top:60vh;object-fit:cover;border-radius:8px;box-shadow:0 1px 3px rgba(0,0,0,.25);z-index:9999;pointer-events:none;transition:none}
    @keyframes tsuru-walk-bounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}
    #tsuru-sprite.tsuru-walking{animation:tsuru-walk-bounce .45s ease-in-out infinite}
    @keyframes tsuru-idle-sway{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-4px) rotate(-1.2deg)}}
    #tsuru-sprite.tsuru-idle{animation:tsuru-idle-sway 2.2s ease-in-out infinite}
    @keyframes tsuru-talk-pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.045)}}
    #tsuru-sprite.tsuru-talking{animation:tsuru-talk-pulse .28s ease-in-out infinite}
    #tsuru-card{position:fixed;left:20px;bottom:20px;max-width:320px;background:#fff;border:1px solid #ddd;border-radius:12px;padding:16px;z-index:9998;font-family:system-ui,-apple-system,sans-serif;font-size:14px;color:#1a1a1a;box-shadow:0 2px 10px rgba(0,0,0,.12)}
    #tsuru-status{position:fixed;left:20px;bottom:210px;max-width:280px;background:rgba(255,255,255,.95);padding:4px 8px;border-radius:6px;font-size:12px;color:#555;z-index:9998;font-family:system-ui,-apple-system,sans-serif}
    #tsuru-progress-wrap{position:fixed;left:20px;bottom:196px;width:280px;height:4px;background:#e5e5e5;border-radius:2px;overflow:hidden;z-index:9998}
    #tsuru-progress-fill{height:100%;background:#3b6ef6;transition:width .3s ease;width:0%}
    .tsuru-opt-btn{margin:4px 8px 4px 0;padding:8px 14px;border:1px solid #ccc;border-radius:8px;background:#fff;cursor:pointer;font-size:14px}
    .tsuru-opt-btn:hover{background:#f0f0f0}
    .tsuru-error-text{color:#b3251e;font-size:12px;margin-top:6px}
    .tsuru-sim-note{font-size:11px;color:#888;margin-top:8px}
    .tsuru-hint{font-size:11px;color:#888;margin-top:6px}
    #tsuru-card pre{background:#f0f0f0;padding:12px;border-radius:8px;font-size:12px;overflow:auto}
  `;
  const styleEl = document.createElement('style');
  styleEl.textContent = css;
  document.head.appendChild(styleEl);

  // ---------- Elementos propios, creados en JS, no dependen del HTML de JC ----------
  const sprite = document.createElement('img');
  sprite.id = 'tsuru-sprite';
  sprite.alt = 'Tsurudenji';
  sprite.src = 'data:image/png;base64,' + SPRITE_B64;
  document.body.appendChild(sprite);

  const progressWrap = document.createElement('div');
  progressWrap.id = 'tsuru-progress-wrap';
  const progressFill = document.createElement('div');
  progressFill.id = 'tsuru-progress-fill';
  progressWrap.appendChild(progressFill);
  document.body.appendChild(progressWrap);

  const statusEl = document.createElement('p');
  statusEl.id = 'tsuru-status';
  statusEl.setAttribute('aria-live', 'polite');
  statusEl.textContent = 'Iniciando…';
  document.body.appendChild(statusEl);

  const card = document.createElement('div');
  card.id = 'tsuru-card';
  document.body.appendChild(card);

  // ---------- Voz ----------
  let voces = [];
  function cargarVoces(){ voces = speechSynthesis.getVoices(); }
  if('speechSynthesis' in window){
    cargarVoces();
    speechSynthesis.onvoiceschanged = cargarVoces;
  }
  function elegirVoz(){
    if(!voces.length) return null;
    const prioridad = ['es-419','es-us','es-mx','es-co','es-pe','es'];
    for(const pref of prioridad){
      const v = voces.find(v => v.lang.toLowerCase().startsWith(pref) && !v.lang.toLowerCase().startsWith('es-es'));
      if(v) return v;
    }
    return voces.find(v => v.lang.toLowerCase().startsWith('es')) || null;
  }
  let modoMovimiento = 'normal';
  let caminando = false;
  let hablando = false;

  function actualizarAnimacion(){
    sprite.classList.remove('tsuru-idle', 'tsuru-walking', 'tsuru-talking');
    if(modoMovimiento === 'sin'){
      // prefers-reduced-motion: cero animación, Tsuru se ve pero no se anima
      return;
    }
    if(caminando) sprite.classList.add('tsuru-walking');
    else if(hablando) sprite.classList.add('tsuru-talking');
    else sprite.classList.add('tsuru-idle');
  }

  function hablar(texto){
    try{
      if('speechSynthesis' in window){
        speechSynthesis.cancel();
        const u = new SpeechSynthesisUtterance(texto);
        const voz = elegirVoz();
        if(voz){ u.voice = voz; u.lang = voz.lang; } else { u.lang = 'es-419'; }
        u.rate = 1.05; u.pitch = 0.95; u.volume = 1;
        u.onstart = () => { hablando = true; actualizarAnimacion(); };
        u.onend = () => { hablando = false; actualizarAnimacion(); };
        u.onerror = () => { hablando = false; actualizarAnimacion(); };
        speechSynthesis.speak(u);
      }
    }catch(e){}
  }

  // ---------- Movimiento: lee el HTML de JC tal cual está ----------
  const HOME = { x: 40, y: window.innerHeight * 0.5 };

  function normalizar(txt){
    return (txt || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  }
  function buscarPorEtiquetas(etiquetas){
    const candidatos = document.querySelectorAll('body *');
    for(const el of candidatos){
      if(el.children.length > 0) continue;
      if(el.closest('#tsuru-card') || el.id === 'tsuru-sprite') continue;
      const texto = normalizar(el.textContent);
      if(!texto) continue;
      if(etiquetas.some(e => texto === normalizar(e))){
        return el.closest('[class]') || el;
      }
    }
    return null;
  }
  function elACoordenadas(el){
    const r = el.getBoundingClientRect();
    return { x: Math.max(8, r.left - 60), y: r.top + window.scrollY };
  }
  sprite.addEventListener('transitionrun', () => { caminando = (modoMovimiento !== 'sin'); actualizarAnimacion(); });
  sprite.addEventListener('transitionend', () => { caminando = false; actualizarAnimacion(); });

  // Etiquetas tal como aparecen en la interfaz real de VólticvS (según el video revisado).
  // Si JC cambia el texto visible de un campo, actualizar acá.
  const ETIQUETAS = {
    aire_acondicionado: ['aire acondicionado'],
    calefaccion_electrica: ['calefaccion electrica'],
    agua_caliente_electrica: ['termotanque / calentador', 'termotanque', 'calentador'],
    secarropas_electrico: ['secarropas electrico'],
    horno_electrico: ['horno o anafe electrico'],
    refrigerador: ['refrigeradores'],
    freezer: ['freezers'],
    tv: ['televisores']
  };

  const WAYPOINTS_REPOSO = [
    { x: 40, y: 0.5 },
    { x: 90, y: 0.42 },
    { x: 55, y: 0.6 },
    { x: 110, y: 0.55 }
  ];
  let waypointIdx = 0;

  function moverA(destinoKey){
    let el = null;
    if(destinoKey){
      el = elementoVisualPara(destinoKey); // 1) mapeo real confirmado con el código de JC
      if(!el) el = document.querySelector('[data-tsuru-target="' + destinoKey + '"]'); // 2) si algún día lo agrega
      if(!el && ETIQUETAS[destinoKey]) el = buscarPorEtiquetas(ETIQUETAS[destinoKey]); // 3) último recurso, por texto
    }
    let punto;
    if(el){
      punto = elACoordenadas(el);
    } else {
      // sin estación mapeada: deambula entre puntos fijos cerca de HOME, nunca queda estático
      const wp = WAYPOINTS_REPOSO[waypointIdx % WAYPOINTS_REPOSO.length];
      waypointIdx++;
      punto = { x: wp.x, y: window.innerHeight * wp.y };
    }
    sprite.style.transition = (modoMovimiento === 'sin') ? 'none' : 'left 2.2s ease-in-out, top 2.2s ease-in-out';
    sprite.style.left = punto.x + 'px';
    sprite.style.top = punto.y + 'px';
  }

  // ---------- Integración real con el HTML/JS de JC ----------
  // Confirmado con su código fuente: estos son los IDs reales de su formulario,
  // y sus claves de payload ya coinciden con nuestros guarda_en (sin traducir nada).
  const MAPEO_CAMPOS = {
    pais:                    { tipo: 'pais-select', id: 'pais' },
    estado_provincia:        { tipo: 'text',    id: 'selectProvincia' },
    dormitorios:             { tipo: 'counter', id: 'inputDormitorios' },
    ventanas:                { tipo: 'counter', id: 'inputVentanas' },
    habitantes_mayores:      { tipo: 'counter', id: 'inputMayores' },
    habitantes_menores:      { tipo: 'counter', id: 'inputMenores' },
    aire_acondicionado:      { tipo: 'toggle',  id: 'aireAcondicionado',     contenedor: 'equipAC' },
    calefaccion_electrica:   { tipo: 'toggle',  id: 'calefaccionElectrica',  contenedor: 'equipCalef' },
    agua_caliente_electrica: { tipo: 'toggle',  id: 'aguaCalienteElectrica', contenedor: 'equipAgua' },
    secarropas_electrico:    { tipo: 'toggle',  id: 'secarropasElectrico',   contenedor: 'equipSeca' },
    horno_electrico:         { tipo: 'toggle',  id: 'hornoElectrico',        contenedor: 'equipHorno' },
    lavado_frecuencia:       { tipo: 'counter', id: 'lavadoFrecuencia' },
    refrigerador:            { tipo: 'counter', id: 'refrigerador' },
    freezer:                 { tipo: 'counter', id: 'freezer' },
    tv:                      { tipo: 'counter', id: 'tv' },
    tv_frecuencia:           { tipo: 'number',  id: 'tvFrecuencia' } // OJO: este campo es horas DIARIAS, no semanales (ver nota en steps)
    // agua_caliente_tamano, flag_galones, luces_exterior, luces_interior: JC los manda
    // hardcodeados a 0 por ahora, no hay campo real en su UI. Pendiente pedírselo.
  };

  // A qué paso del wizard de JC (1-4) pertenece cada campo, para sincronizar showStep()
  const JC_STEP_POR_CAMPO = {
    pais: 1, estado_provincia: 1,
    dormitorios: 2, ventanas: 2, habitantes_mayores: 2, habitantes_menores: 2,
    aire_acondicionado: 3, calefaccion_electrica: 3, agua_caliente_electrica: 3, secarropas_electrico: 3, horno_electrico: 3,
    lavado_frecuencia: 4, refrigerador: 4, freezer: 4, tv: 4, tv_frecuencia: 4
  };
  let ultimoJCStep = 0;

  function sincronizarPasoJC(guardaEn){
    const paso = JC_STEP_POR_CAMPO[guardaEn];
    if(paso && paso !== ultimoJCStep && typeof window.showStep === 'function'){
      window.showStep(paso);
      ultimoJCStep = paso;
    }
  }

  function elementoVisualPara(guardaEn){
    const campo = MAPEO_CAMPOS[guardaEn];
    if(!campo) return null;
    if(campo.contenedor) return document.getElementById(campo.contenedor);
    const el = document.getElementById(campo.id);
    return el ? (el.closest('.form-group') || el) : null;
  }

  function fijarPaisPorNombre(nombre){
    const sel = document.getElementById('pais');
    if(!sel) return false;
    const nombreNorm = normalizar(nombre);
    const opt = Array.from(sel.options).find(o => normalizar(o.textContent).includes(nombreNorm));
    if(opt){
      sel.value = opt.value;
      sel.dispatchEvent(new Event('change', { bubbles: true }));
      return true;
    }
    return false;
  }

  function escribirValor(guardaEn, valor){
    const campo = MAPEO_CAMPOS[guardaEn];
    if(!campo) return false;
    if(campo.tipo === 'pais-select'){ return fijarPaisPorNombre(valor); }
    const el = document.getElementById(campo.id);
    if(!el) return false;
    if(campo.tipo === 'toggle'){
      el.checked = !!valor;
      el.dispatchEvent(new Event('change', { bubbles: true }));
    } else {
      el.value = valor;
      el.dispatchEvent(new Event('input', { bubbles: true }));
    }
    return true;
  }


  const respuestas = {};
  let idx = 0;

  const steps = [
    {id:'accesibilidad', tipo:'accesibilidad'},
    {id:'ubicacion', tipo:'ubicacion'},
    {id:'dormitorios', tipo:'number', texto:'¿Cuántos dormitorios tiene la vivienda? Si es un monoambiente, responde cero.', guarda_en:'dormitorios'},
    {id:'ventanas', tipo:'number', texto:'¿Cuántas ventanas y puertas balcón tiene la vivienda en total?', guarda_en:'ventanas'},
    {id:'habitantes_mayores', tipo:'number', texto:'¿Cuántos habitantes de 18 años o más viven en la vivienda?', guarda_en:'habitantes_mayores'},
    {id:'habitantes_menores', tipo:'number', texto:'¿Cuántos habitantes de 17 años o menos viven en la vivienda?', guarda_en:'habitantes_menores'},
    {id:'aire_acondicionado', tipo:'boolean_int', texto:'¿La vivienda tiene aire acondicionado?', guarda_en:'aire_acondicionado'},
    {id:'calefaccion_electrica', tipo:'boolean_int', texto:'¿La calefacción principal de la vivienda es eléctrica?', guarda_en:'calefaccion_electrica'},
    {id:'agua_caliente_electrica', tipo:'boolean_int', texto:'¿El agua caliente para ducha y lavado de platos se calienta principalmente con electricidad?', guarda_en:'agua_caliente_electrica'},
    {id:'secarropas_electrico', tipo:'boolean_int', texto:'¿La vivienda tiene secarropas eléctrico?', guarda_en:'secarropas_electrico'},
    {id:'desea_extendida', tipo:'boolean_int', texto:'Con esto ya puedo darte una estimación. ¿Quieres continuar con la versión extendida para afinar el resultado?', guarda_en:'desea_version_extendida', esGate:true},
    {id:'horno_electrico', tipo:'boolean_int', texto:'¿El horno principal de la vivienda es eléctrico?', guarda_en:'horno_electrico', avanzada:true},
    {id:'agua_caliente_tamano', tipo:'number', texto:'¿Qué tamaño tiene el termo de agua caliente semi industrial?', guarda_en:'agua_caliente_tamano', avanzada:true},
    {id:'flag_galones', tipo:'choice', texto:'¿Esa medida la diste en galones o en litros?', opciones:[{label:'Galones',valor:1},{label:'Litros',valor:2}], guarda_en:'flag_galones', avanzada:true},
    {id:'lavado_frecuencia', tipo:'number', texto:'¿Cuántas veces por semana lava la ropa?', guarda_en:'lavado_frecuencia', avanzada:true},
    {id:'refrigerador', tipo:'number', texto:'¿Cuántos refrigeradores tiene la vivienda?', guarda_en:'refrigerador', avanzada:true},
    {id:'freezer', tipo:'number', texto:'¿Cuántos freezers independientes del refrigerador tiene la vivienda?', guarda_en:'freezer', avanzada:true},
    {id:'luces_exterior', tipo:'number', texto:'¿Cuántas luces tiene fuera de la vivienda?', guarda_en:'luces_exterior', avanzada:true},
    {id:'luces_interior', tipo:'number', texto:'¿Cuántas luces tiene dentro de la vivienda?', guarda_en:'luces_interior', avanzada:true},
    {id:'tv', tipo:'number', texto:'¿Cuántos televisores tiene la vivienda?', guarda_en:'tv', avanzada:true},
    {id:'tv_frecuencia', tipo:'number', texto:'¿Cuántas horas al día está encendido el televisor principal?', guarda_en:'tv_frecuencia', avanzada:true},
    {id:'resumen', tipo:'resumen'}
  ];

  function updateProgress(){
    const total = steps.length - 1;
    progressFill.style.width = Math.round((idx/total)*100) + '%';
  }
  function goNext(){
    idx++;
    const cur = steps[idx];
    if(cur && cur.avanzada && respuestas.desea_version_extendida === 0){
      while(steps[idx] && steps[idx].avanzada){ idx++; }
    }
    render();
  }
  function guardarYAvanzar(campo, valor){
    respuestas[campo] = valor;
    escribirValor(campo, valor);
    goNext();
  }
  function preguntarSiOmitir(step){
    const texto = '¿Estás seguro de que quieres enviar sin responder esta pregunta? Quedará como que no la respondiste.';
    statusEl.textContent = 'Tsurudenji: ' + texto;
    hablar(texto);
    card.innerHTML = '<p style="margin:0 0 12px">' + texto + '</p>';
    const si = document.createElement('button'); si.className='tsuru-opt-btn'; si.textContent='No, quiero responderla';
    si.onclick = () => render();
    const no = document.createElement('button'); no.className='tsuru-opt-btn'; no.textContent='Sí, omitirla';
    no.onclick = () => goNext();
    card.appendChild(si); card.appendChild(no);
  }

  function render(){
    updateProgress();
    const step = steps[idx];
    card.innerHTML = '';
    sincronizarPasoJC(step.guarda_en);
    moverA(MAPEO_CAMPOS[step.guarda_en] || ETIQUETAS[step.guarda_en] ? step.guarda_en : null);

    if(step.tipo === 'accesibilidad'){
      const reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
      const dark = window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches;
      modoMovimiento = reduce ? 'sin' : 'normal';
      const resumen = (reduce ? 'movimiento reducido' : 'movimiento normal') + ', ' + (dark ? 'modo oscuro' : 'modo claro');
      const texto = 'Detecté que tu sistema tiene ' + resumen + '. Voy a usar esta configuración para que la experiencia sea más cómoda. ¿Quieres mantenerla así?';
      statusEl.textContent = 'Tsurudenji: ' + texto;
      hablar(texto);
      card.innerHTML = '<p style="margin:0 0 12px">' + texto + '</p>';
      const si = document.createElement('button'); si.className='tsuru-opt-btn'; si.textContent='Sí, mantenerla';
      si.onclick = () => guardarYAvanzar('config_accesibilidad', resumen);
      const no = document.createElement('button'); no.className='tsuru-opt-btn'; no.textContent='No, usar valores por defecto';
      no.onclick = () => { modoMovimiento='normal'; guardarYAvanzar('config_accesibilidad', 'por_defecto'); };
      card.appendChild(si); card.appendChild(no);
      return;
    }

    if(step.tipo === 'ubicacion'){
      const texto = 'Detecté que estás en San Fernando, Región de O\'Higgins, Chile. ¿Es correcto?';
      statusEl.textContent = 'Tsurudenji: ' + texto;
      hablar(texto);
      card.innerHTML = '<p style="margin:0 0 4px">' + texto + '</p><p class="tsuru-sim-note">Ubicación simulada — en producción se obtiene por geolocalización real + reverse geocoding a nivel de comuna.</p>';
      const si = document.createElement('button'); si.className='tsuru-opt-btn'; si.textContent='Sí, es correcto';
      si.onclick = () => {
        respuestas.pais='Chile'; respuestas.estado_provincia="O'Higgins"; respuestas.comuna='San Fernando';
        escribirValor('pais', 'Chile');
        escribirValor('estado_provincia', "O'Higgins");
        goNext();
      };
      const no = document.createElement('button'); no.className='tsuru-opt-btn'; no.textContent='No, corregir';
      no.onclick = () => renderUbicacionManual();
      card.appendChild(si); card.appendChild(no);
      return;
    }

    if(step.tipo === 'number'){
      statusEl.textContent = 'Tsurudenji: ' + step.texto;
      hablar(step.texto);
      card.innerHTML = '<p style="margin:0 0 14px">' + step.texto + '</p>' +
        '<div style="display:flex;align-items:center;gap:10px">' +
        '<button class="tsuru-opt-btn" id="tsuru-num-menos" style="width:36px;font-size:18px;padding:6px 0">−</button>' +
        '<span id="tsuru-num-valor" style="min-width:30px;text-align:center;font-size:18px;font-weight:600">0</span>' +
        '<button class="tsuru-opt-btn" id="tsuru-num-mas" style="width:36px;font-size:18px;padding:6px 0">+</button>' +
        '</div><div style="margin-top:14px">' +
        '<button class="tsuru-opt-btn" id="tsuru-num-submit">Confirmar</button>' +
        '<button class="tsuru-opt-btn" id="tsuru-num-omitir">No quiero responder</button></div>';
      let valor = 0;
      const valorEl = document.getElementById('tsuru-num-valor');
      document.getElementById('tsuru-num-menos').onclick = () => { if(valor>0){ valor--; valorEl.textContent=valor; } };
      document.getElementById('tsuru-num-mas').onclick = () => { valor++; valorEl.textContent=valor; };
      document.getElementById('tsuru-num-submit').onclick = () => guardarYAvanzar(step.guarda_en, valor);
      document.getElementById('tsuru-num-omitir').onclick = () => preguntarSiOmitir(step);
      return;
    }

    if(step.tipo === 'boolean_int'){
      statusEl.textContent = 'Tsurudenji: ' + step.texto;
      hablar(step.texto);
      card.innerHTML = '<p style="margin:0 0 12px">' + step.texto + '</p>';
      const si = document.createElement('button'); si.className='tsuru-opt-btn'; si.textContent='Sí';
      si.onclick = () => guardarYAvanzar(step.guarda_en, 1);
      const no = document.createElement('button'); no.className='tsuru-opt-btn'; no.textContent='No';
      no.onclick = () => guardarYAvanzar(step.guarda_en, 0);
      card.appendChild(si); card.appendChild(no);
      return;
    }

    if(step.tipo === 'choice'){
      statusEl.textContent = 'Tsurudenji: ' + step.texto;
      hablar(step.texto);
      card.innerHTML = '<p style="margin:0 0 12px">' + step.texto + '</p>';
      step.opciones.forEach(op => {
        const b = document.createElement('button'); b.className='tsuru-opt-btn'; b.textContent=op.label;
        b.onclick = () => guardarYAvanzar(step.guarda_en, op.valor);
        card.appendChild(b);
      });
      return;
    }

    if(step.tipo === 'resumen'){
      const btnSubmit = document.getElementById('btnSubmit');
      if(btnSubmit){
        const texto = 'Listo, ya tengo todo. Voy a calcular tu consumo.';
        statusEl.textContent = 'Tsurudenji: ' + texto;
        hablar(texto);
        card.innerHTML = '<p style="margin:0 0 10px">' + texto + '</p>';
        btnSubmit.click(); // dispara el cálculo real de VólticvS, con los datos que ya escribimos en su formulario
      } else {
        // fallback: si no encontró el botón real (ej. probando este script fuera de la página de JC)
        const texto = 'Te hago el resumen.';
        statusEl.textContent = 'Tsurudenji: ' + texto;
        hablar(texto);
        card.innerHTML = '<p style="margin:0 0 10px">' + texto + '</p><pre>' + JSON.stringify(respuestas, null, 2) + '</pre>';
      }
      return;
    }
  }

  function renderUbicacionManual(){
    card.innerHTML = '<p style="margin:0 0 8px">¿En qué país te encuentras?</p><input id="tsuru-pais" type="text" style="width:200px" />' +
      '<p style="margin:12px 0 8px">¿En qué estado o provincia?</p><input id="tsuru-estado" type="text" style="width:200px" />' +
      '<p style="margin:12px 0 8px">¿En qué comuna o ciudad?</p><input id="tsuru-comuna" type="text" style="width:200px" />' +
      '<div style="margin-top:12px"><button class="tsuru-opt-btn" id="tsuru-ubi-submit">Continuar</button></div>';
    document.getElementById('tsuru-ubi-submit').onclick = () => {
      respuestas.pais = document.getElementById('tsuru-pais').value || 'No especificado';
      respuestas.estado_provincia = document.getElementById('tsuru-estado').value || 'No especificado';
      respuestas.comuna = document.getElementById('tsuru-comuna').value || 'No especificado';
      escribirValor('pais', respuestas.pais);
      escribirValor('estado_provincia', respuestas.estado_provincia);
      goNext();
    };
  }

  // ---------- Auto-inicio ----------
  actualizarAnimacion();
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', render);
  } else {
    render();
  }
})();
